const crypto = require('crypto');

const appSecret = $env.WHATSAPP_APP_SECRET;
const signature = $json.headers['x-hub-signature-256'];

let binaryDataBuffer;
try {
  binaryDataBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (e) {
  throw new Error('Failed to read raw body from binary data: ' + e.message);
}

const body = binaryDataBuffer.toString('utf8');

if (!signature) {
  throw new Error('Missing X-Hub-Signature-256 header');
}

const expectedSignature = 'sha256=' + crypto
  .createHmac('sha256', appSecret)
  .update(body)
  .digest('hex');

if (signature !== expectedSignature) {
  throw new Error('Invalid webhook signature — request rejected');
}

return [{ json: $json }];

const msg = $('Normalize: Extract Payload').first().json.message?.toLowerCase().trim();
const rows = $input.all();

// Find all active conversations and sort by ID descending (most recent first)
const activeRows = rows.filter(row => row.json.id && row.json.state !== 'idle' && row.json.completed !== true)
                       .sort((a, b) => b.json.id - a.json.id);
const activeRow = activeRows[0];

let restartRequired = false;
let currentConversation = {};

if (!activeRow) {
  // No active conversation exists -> must create a new one
  restartRequired = true;
} else {
  // Active conversation exists -> check for manual restart keyword or 24h timeout
  const updatedAt = activeRow.json.updated_at ? new Date(activeRow.json.updated_at).getTime() : 0;
  const now = new Date().getTime();
  const hoursSinceUpdate = updatedAt ? (now - updatedAt) / 3600000 : 0;

  const isRestartKeyword = msg === 'restart' || msg === 'start';
  const isTimeout = hoursSinceUpdate > 24;

  if (isRestartKeyword || isTimeout) {
    restartRequired = true;
    currentConversation = activeRow.json;
  } else {
    // Continue with the active conversation
    currentConversation = activeRow.json;
  }
}

return [{
  json: {
    ...currentConversation,
    restart_required: restartRequired
  }
}];

let binaryDataBuffer;
try {
  binaryDataBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (e) {
  throw new Error('Failed to read binary data buffer: ' + e.message);
}
return [{
  json: {
    base64_data: binaryDataBuffer.toString('base64')
  }
}];

