const text = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || '';
let parsed = { name: null, company: null, email: null, ride: null, number_of_passengers: null, from_place: null, to_place: null, from_date: null, to_date: null };
try {
  const jsonStr = text.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(jsonStr);
} catch (e) {}

if (parsed.ride) {
  const v = String(parsed.ride).toLowerCase().trim();
  if (v === '1' || v.includes('helicopter')) parsed.ride = 'Helicopter Ride';
  else if (v === '2' || v.includes('yacht')) parsed.ride = 'Yacht Charter';
  else if (v === '3' || v.includes('jet') || v.includes('private')) parsed.ride = 'Private Jet';
  else if (v === '4' || v.includes('car') || v.includes('luxury')) parsed.ride = 'Luxury Car';
  else if (v === '5' || v.includes('other')) parsed.ride = 'Other';
}

const isValidEmail = !parsed.email || parsed.email === 'skip' || (parsed.email.includes('@') && parsed.email.includes('.'));
const allFieldsPresent = parsed.name && parsed.ride && parsed.number_of_passengers && parsed.from_place && parsed.to_place && parsed.from_date && isValidEmail;

return [{
  json: {
    all_fields_present: !!allFieldsPresent,
    name: parsed.name || null,
    company: parsed.company || 'skip',
    email: parsed.email || 'skip',
    ride: parsed.ride || null,
    number_of_passengers: parsed.number_of_passengers ? String(parsed.number_of_passengers) : null,
    from_place: parsed.from_place || null,
    to_place: parsed.to_place || null,
    from_date: parsed.from_date || null,
    to_date: parsed.to_date || 'skip'
  }
}];

